files.content:
.root {
  /* Vitrina spine roles */
  --vt-surface: #F4F1DE;
  --vt-surface-2: #FFFFFF;
  --vt-surface-deep: #3D405B;
  --vt-ink: #3D405B;
  --vt-ink-soft: #575a78;
  --vt-on-deep: #F4F1DE;
  --vt-accent: #E07A5F;
  --vt-on-accent: #FFFFFF;
  --vt-accent-ink: #C4603F;
  --vt-accent-on-deep: #A8CFBA;
  --vt-line: rgba(61, 64, 91, 0.1);
}

.navToggle {
  position: absolute;
  opacity: 0;
  pointer-events: none;
}

.hamburger {
  display: none;
  position: fixed;
  top: 1rem;
  left: 1rem;
  z-index: 1100;
  width: 48px;
  height: 48px;
  background: var(--vt-surface-deep);
  border-radius: 8px;
  align-items: center;
  justify-content: center;
  box-shadow: 0 4px 24px rgba(61, 64, 91, 0.08);
  cursor: pointer;
}

.hamburgerLine {
  display: block;
  width: 22px;
  height: 2px;
  background: var(--vt-on-deep);
  margin: 4px 0;
  transition: all 0.3s cubic-bezier(0.22, 1, 0.36, 1);
}

.navToggle:checked ~ .hamburger .hamburgerLine:nth-child(1) {
  transform: translateY(6px) rotate(45deg);
}

.navToggle:checked ~ .hamburger .hamburgerLine:nth-child(2) {
  opacity: 0;
}

.navToggle:checked ~ .hamburger .hamburgerLine:nth-child(3) {
  transform: translateY(-6px) rotate(-45deg);
}

.overlay {
  display: none;
  position: fixed;
  inset: 0;
  background: rgba(61, 64, 91, 0.5);
  z-index: 999;
  opacity: 0;
  transition: opacity 0.3s ease;
  pointer-events: none;
}

.navToggle:checked ~ .overlay {
  display: block;
  opacity: 1;
  pointer-events: auto;
}

.sidebar {
  position: fixed;
  top: 0;
  left: 0;
  width: 260px;
  height: 100vh;
  background: var(--vt-surface-deep);
  color: var(--vt-on-deep);
  display: flex;
  flex-direction: column;
  z-index: 1000;
  overflow-y: auto;
  transition: transform 0.4s cubic-bezier(0.22, 1, 0.36, 1);
}

.sidebarBrand {
  padding: 2rem 1.5rem 1.5rem;
  border-bottom: 1px solid rgba(244, 241, 222, 0.1);
}

.sidebarNav {
  flex: 1;
  padding: 1.5rem 0;
}

.sidebarNav ul {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.navLink {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  padding: 0.75rem 1.5rem;
  font-size: 0.9rem;
  font-weight: 500;
  color: rgba(244, 241, 222, 0.65);
  text-decoration: none;
  transition: all 0.3s cubic-bezier(0.22, 1, 0.36, 1);
  position: relative;
}

.navLink::before {
  content: '';
  position: absolute;
  left: 0;
  top: 50%;
  transform: translateY(-50%) scaleY(0);
  width: 3px;
  height: 70%;
  background: var(--vt-accent);
  border-radius: 0 3px 3px 0;
  transition: transform 0.3s cubic-bezier(0.22, 1, 0.36, 1);
}

.navLink:hover,
.navLink:focus-visible {
  color: var(--vt-on-deep);
  background: rgba(244, 241, 222, 0.06);
  outline: none;
}

.navLink:hover::before,
.navLink:focus-visible::before {
  transform: translateY(-50%) scaleY(1);
}

.navIcon {
  width: 20px;
  text-align: center;
  font-size: 1.1rem;
  flex-shrink: 0;
}

.sidebarFooter {
  padding: 1.5rem;
  border-top: 1px solid rgba(244, 241, 222, 0.1);
}

.sidebarHours {
  font-size: 0.78rem;
  color: rgba(244, 241, 222, 0.5);
  line-height: 1.6;
}

.sidebarHours strong {
  color: var(--vt-accent-on-deep);
  font-weight: 600;
}

.main {
  margin-left: 260px;
  min-height: 100vh;
}

.hero {
  position: relative;
  min-height: 100vh;
  display: flex;
  align-items: center;
  padding: clamp(3rem, 6vw, 6rem);
  background:
    radial-gradient(ellipse at 20% 80%, rgba(129, 178, 154, 0.15) 0%, transparent 50%),
    radial-gradient(ellipse at 80% 20%, rgba(224, 122, 95, 0.12) 0%, transparent 50%),
    var(--vt-surface);
  overflow: hidden;
}

.heroContent {
  max-width: 640px;
  position: relative;
  z-index: 2;
}

.heroBadge {
  display: inline-block;
  padding: 0.4rem 1rem;
  background: var(--vt-accent-ink);
  color: var(--vt-on-accent);
  font-size: 0.72rem;
  font-weight: 700;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  border-radius: 50px;
  margin-bottom: 1.5rem;
}

.heroTitle {
  font-size: clamp(2.8rem, 6vw, 4.5rem);
  font-weight: 700;
  color: var(--vt-ink);
  margin-bottom: 0.5rem;
  letter-spacing: -0.03em;
  line-height: 1.2;
}

.heroTitle em {
  color: var(--vt-accent);
  font-style: italic;
}

.heroSubtitle {
  font-size: clamp(1rem, 2vw, 1.25rem);
  color: var(--vt-ink-soft);
  margin-bottom: 2rem;
  max-width: 480px;
}

.heroActions {
  display: flex;
  flex-wrap: wrap;
  gap: 1rem;
}

.btn {
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  padding: 0.85rem 1.75rem;
  font-size: 0.9rem;
  font-weight: 600;
  border-radius: 14px;
  text-decoration: none;
  transition: all 0.3s cubic-bezier(0.22, 1, 0.36, 1);
}

.btn:focus-visible {
  outline: 2px solid var(--vt-accent);
  outline-offset: 2px;
}

.btnPrimary {
  background: var(--vt-accent);
  color: var(--vt-on-accent);
}

.btnPrimary:hover {
  background: var(--vt-accent-ink);
  transform: translateY(-2px);
  box-shadow: 0 6px 24px rgba(224, 122, 95, 0.35);
}

.btnOutline {
  border: 2px solid var(--vt-ink);
  color: var(--vt-ink);
  background: transparent;
}

.btnOutline:hover {
  background: var(--vt-ink);
  color: var(--vt-on-deep);
  transform: translateY(-2px);
}

.heroDeco {
  position: absolute;
  right: -2%;
  top: 50%;
  transform: translateY(-50%);
  width: clamp(280px, 35vw, 500px);
  height: clamp(280px, 35vw, 500px);
  z-index: 1;
}

.scoop {
  position: absolute;
  border-radius: 50%;
  box-shadow: inset 0 -10px 30px rgba(0, 0, 0, 0.08), 0 6px 20px rgba(0, 0, 0, 0.06);
}

.scoopHighlight {
  position: absolute;
  width: 25%;
  height: 25%;
  background: rgba(255, 255, 255, 0.5);
  border-radius: 50%;
  top: 15%;
  left: 20%;
  filter: blur(6px);
}

.scoopStrawberry {
  width: 60%;
  height: 60%;
  background: radial-gradient(circle at 35% 35%, #f4a4b8, var(--vt-accent));
  top: 0;
  right: 10%;
}

.scoopMint {
  width: 50%;
  height: 50%;
  background: radial-gradient(circle at 35% 35%, var(--vt-accent-on-deep), #5f8e73);
  bottom: 8%;
  right: 0;
}

.scoopVanilla {
  width: 45%;
  height: 45%;
  background: radial-gradient(circle at 35% 35%, #fff5e0, #e8e3c8);
  bottom: 15%;
  left: 5%;
}

.section {
  padding: var(--section-pad, clamp(3rem, 6vw, 6rem));
}

.sectionAlt {
  background: var(--vt-surface-2);
}

.sectionHeader {
  margin-bottom: clamp(2rem, 4vw, 3.5rem);
}

.sectionLabel {
  display: inline-block;
  font-size: 0.72rem;
  font-weight: 700;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--vt-accent);
  margin-bottom: 0.75rem;
}

.sectionTitle {
  font-size: clamp(1.8rem, 4vw, 2.8rem);
  color: var(--vt-ink);
  letter-spacing: -0.02em;
  margin: 0;
}

.sectionDesc {
  margin-top: 0.75rem;
  font-size: 1.05rem;
  color: var(--vt-ink-soft);
  max-width: 560px;
}

.builder {
  background:
    radial-gradient(ellipse at 70% 30%, rgba(224, 122, 95, 0.06) 0%, transparent 50%),
    var(--vt-surface-2);
}

.builderLayout {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: clamp(2rem, 4vw, 4rem);
  align-items: start;
}

.builderSteps {
  display: flex;
  flex-direction: column;
  gap: 1.5rem;
}

.builderStep {
  display: flex;
  gap: 1.25rem;
  padding: 1.5rem;
  background: var(--vt-surface);
  border-radius: 14px;
  transition: all 0.3s cubic-bezier(0.22, 1, 0.36, 1);
}

.builderStep:hover {
  box-shadow: 0 4px 24px rgba(61, 64, 91, 0.08);
}

.builderStepNum {
  flex-shrink: 0;
  width: 44px;
  height: 44px;
  background: var(--vt-accent);
  color: var(--vt-on-accent);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-family: Georgia, serif;
  font-weight: 700;
  font-size: 1.1rem;
}

.builderStepTitle {
  font-family: Georgia, serif;
  font-size: 1.1rem;
  font-weight: 600;
  color: var(--vt-ink);
  margin-bottom: 0.25rem;
}

.builderStepText {
  font-size: 0.88rem;
  color: var(--vt-ink-soft);
  margin: 0;
}

.builderStepPrice {
  display: inline-block;
  margin-top: 0.5rem;
  font-size: 0.8rem;
  font-weight: 700;
  color: var(--vt-accent);
}

.builderPreview {
  background: var(--vt-surface);
  border-radius: 32px;
  padding: 2.5rem;
  text-align: center;
  position: relative;
  min-height: 400px;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  position: sticky;
  top: 2rem;
}

.builderPreviewBowl {
  width: 200px;
  height: 110px;
  background: linear-gradient(135deg, var(--vt-ink), var(--vt-ink-soft));
  border-radius: 0 0 50% 50% / 0 0 100% 100%;
  position: relative;
  margin: 0 auto 1.5rem;
}

.builderPreviewBowl::before {
  content: '';
  position: absolute;
  top: -6px;
  left: -10px;
  right: -10px;
  height: 20px;
  background: var(--vt-ink);
  border-radius: 50%;
}

.builderPreviewScoop {
  border-radius: 50%;
  position: absolute;
  box-shadow: inset 0 -6px 15px rgba(0, 0, 0, 0.08);
}

.builderPreviewScoop1 {
  width: 90px;
  height: 90px;
  background: radial-gradient(circle at 35% 35%, #fce4b8, #e6c68a);
  top: -55px;
  left: 20px;
}

.builderPreviewScoop2 {
  width: 90px;
  height: 90px;
  background: radial-gradient(circle at 35% 35%, #f4a4b8, #e07a8a);
  top: -55px;
  right: 20px;
}

.builderPreviewScoop3 {
  width: 80px;
  height: 80px;
  background: radial-gradient(circle at 35% 35%, var(--vt-accent-on-deep), var(--vt-accent));
  top: -90px;
  left: 50%;
  transform: translateX(-50%);
}

.builderPreviewText {
  font-family: Georgia, serif;
  font-size: 1.15rem;
  color: var(--vt-ink);
  font-weight: 500;
  margin: 0;
}

.builderPreviewNote {
  font-size: 0.8rem;
  color: var(--vt-ink-soft);
  margin-top: 0.25rem;
}

.galleryGrid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(280px, 1fr));
  gap: 1.5rem;
}

.galleryItem {
  margin: 0;
  border-radius: 24px;
  overflow: hidden;
  box-shadow: 0 4px 24px rgba(61, 64, 91, 0.08);
  transition: all 0.4s cubic-bezier(0.22, 1, 0.36, 1);
}

.galleryItem:hover {
  box-shadow: 0 8px 40px rgba(61, 64, 91, 0.14);
  transform: translateY(-4px);
}

.galleryItem img {
  width: 100%;
  height: 220px;
  object-fit: cover;
}

.galleryItem figcaption {
  padding: 1rem;
  background: var(--vt-surface-2);
}

.galleryItem figcaption span {
  display: block;
  font-size: 0.9rem;
  color: var(--vt-ink);
}

.galleryItem figcaption span:last-child {
  font-size: 0.8rem;
  color: var(--vt-ink-soft);
  margin-top: 0.25rem;
}

.galleryTabs {
  position: relative;
}

.tabInput {
  position: absolute;
  opacity: 0;
  pointer-events: none;
}

.seasonalTab {
  display: inline-block;
  padding: 0.75rem 1.25rem;
  background: rgba(61, 64, 91, 0.05);
  border: 2px solid transparent;
  border-radius: 14px;
  font-family: 'Manrope', 'Segoe UI', sans-serif;
  font-size: 0.82rem;
  font-weight: 600;
  color: var(--vt-ink-soft);
  cursor: pointer;
  transition: all 0.35s cubic-bezier(0.22, 1, 0.36, 1);
  text-align: center;
  position: relative;
  margin-right: 4px;
}

.seasonalTab:hover {
  background: rgba(61, 64, 91, 0.09);
  color: var(--vt-ink);
}

.tabInput:checked + .seasonalTab {
  background: var(--vt-accent);
  color: var(--vt-on-accent);
  border-color: transparent;
}

.tabInput:focus-visible + .seasonalTab {
  outline: 2px solid var(--vt-accent);
  outline-offset: 2px;
}

.tabPanels {
  margin-top: 1.5rem;
}

.tabPanel {
  display: none;
}

.tabPanelActive {
  display: block;
  animation: fadeIn 0.5s cubic-bezier(0.22, 1, 0.36, 1);
}

@keyframes fadeIn {
  from { opacity: 0; transform: translateY(12px); }
  to { opacity: 1; transform: translateY(0); }
}

.aboutContent {
  max-width: 800px;
  font-size: 1rem;
  line-height: 1.7;
  color: var(--vt-ink-soft);
}

.footer {
  padding: 3rem var(--section-pad, clamp(3rem, 6vw, 6rem)) 2rem;
  background: var(--vt-surface-deep);
  color: rgba(244, 241, 222, 0.6);
}

.footerTop {
  display: flex;
  flex-wrap: wrap;
  justify-content: space-between;
  gap: 2rem;
  padding-bottom: 2rem;
  border-bottom: 1px solid rgba(244, 241, 222, 0.1);
}

.footerBrand {
  font-family: Georgia, serif;
  font-size: 1.6rem;
  font-weight: 700;
  color: var(--vt-on-deep);
  margin-bottom: 0.5rem;
}

.footerBrand span {
  color: var(--vt-accent);
}

.footerCopy {
  font-size: 0.85rem;
  max-width: 300px;
}

.footerLinks {
  display: flex;
  flex-wrap: wrap;
  gap: 2rem 4rem;
}

.footerCol {
  min-width: 140px
